/* W10_M01_TRAVEL_DIRECT_V1 */
const s=$json.signal||null;if(!s)return [];const r=s.raw_data||{};
const slugify=v=>String(v||'').toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-+|-+$/g,'').slice(0,120);
const intent=String(r.intent||r.editorial_type||'travel_guide');const destination=String(r.destination||s.query||s.title||'').trim();
const title=String(r.title||s.title||`10 things to know about ${destination}`).slice(0,300);
const subject=String(r.subject||destination).slice(0,300);
const slug=slugify(r.destination_slug?`${r.editorial_type||intent}-${r.destination_slug}`:title);
const candidate={slug,title,subject,category:'travel',rationale:`Editorial travel fallback for ${destination}. This topic builds the destination knowledge base when live trends do not yield suitable evergreen content.`,score:0.94,evergreen_score:0.96,source_kind:'travel_seed',intent,destination,location_type:String(r.location_type||'location'),market_weight:Number(r.market_weight)||0.5};
return [{json:{signal_id:s.id,status:'mapped',candidates:[candidate],error:''}}];

/* W10_M01_PROMPT_V2 */
const s=$json.signal||null;if(!s)return [];
const categories=['science-nature','world','history-culture','general-knowledge','technology','travel','home-living','money','everyday','buying-guides'];
const system=`You are the topic editor for What10Things.co.uk. A live trend is only a discovery signal. Map it to at most ONE durable, non-breaking-news subject that people would still benefit from understanding months later. Return STRICT JSON only, no markdown. Schema: {decision:'map'|'ignore',candidate:{slug,title,subject,category,rationale,score,evergreen_score}|null}. Rules: do not write or summarise the breaking event; do not speculate; ignore celebrity gossip, sports scores, one-off TV episodes, betting, explicit content, or a topic whose only value is current news. Location, destination and travel background is a strategic priority, so prefer a useful place/travel explainer where the trend genuinely points to a location, but never force unrelated news into travel. Also prefer science, history, technology, practical life and background knowledge. slug must be lowercase words joined by hyphens. title should naturally promise exactly 10 useful facts or things. category must be one of ${categories.join(', ')}. score and evergreen_score are 0..1 and mapping requires evergreen_score >=0.78.`;
const user=JSON.stringify({trend:{title:s.title,query:s.query,source:s.source,metric_name:s.metric_name,metric_value:s.metric_value,observed_at:s.observed_at,raw_data:s.raw_data||{}}});
return [{json:{signal:s,system,user}}];

/* W10_M01_PARSE_V2 */
const base=$('Build evergreen mapping prompt').item.json;const s=base.signal;
const raw=String($json?.choices?.[0]?.message?.content||'').replace(/```json|```/gi,'').trim();let x=null;try{x=JSON.parse(raw);}catch{}
const allowed=new Set(['science-nature','world','history-culture','general-knowledge','technology','travel','home-living','money','everyday','buying-guides']);
const slugify=v=>String(v||'').toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-+|-+$/g,'').slice(0,120);
let candidates=[];let status='ignored';let error='';
if(x&&x.decision==='map'&&x.candidate){const q=x.candidate;const evergreen=Number(q.evergreen_score),score=Number(q.score);const slug=slugify(q.slug||q.subject||q.title);if(slug&&allowed.has(String(q.category))&&Number.isFinite(evergreen)&&evergreen>=0.78&&Number.isFinite(score)&&score>=0.60){candidates=[{slug,title:String(q.title||`10 things to know about ${q.subject||s.query}`).slice(0,300),subject:String(q.subject||s.query).slice(0,300),category:String(q.category),rationale:String(q.rationale||'Mapped from a public-interest trend into an evergreen explainer.').slice(0,1200),score:Math.min(1,Math.max(0,score)),evergreen_score:Math.min(1,Math.max(0,evergreen)),source_kind:'trend'}];status='mapped';}else{error='Mapper returned a candidate below the evergreen/quality gate';}}
else if(!x){status='retry';error='Free model did not return valid mapping JSON';}
return [{json:{signal_id:s.id,status,candidates,error}}];
